fn boxo(x: i32, y: i32, s: i32, c: i32) {
    host::display::fill_rect(x, y, s, 2, c);
    host::display::fill_rect(x, y + s - 2, s, 2, c);
    host::display::fill_rect(x, y, 2, s, c);
    host::display::fill_rect(x + s - 2, y, 2, s, c);
}

fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let m: i32 = if w < h { w } else { h };
    let cellw: i32 = m / 4;
    let pal = [0xe8e6e3, 0x7fd1b9, 0xd17f97, 0x8a7fd1];
    host::display::clear(0x0e0e12);
    let mut r: i32 = 0;
    while r < 4 {
        let mut c: i32 = 0;
        while c < 4 {
            let mut hsh: i32 = r * 7919 + c * 104729 + 3;
            hsh = hsh * 1103515245 + 12345;
            let ph: i32 = (hsh >> 16) & 31;
            let col: i32 = pal[(hsh >> 8) & 3];
            let ox: i32 = c * cellw;
            let oy: i32 = r * cellw;
            let mut j: i32 = 0;
            while j < 5 {
                let breathe: i32 = (tab[(t * 3 + ph + j * 2) & 31] + 127) * 8 / 254;
                let inset: i32 = 6 + j * 11 + breathe;
                let s: i32 = cellw - inset * 2;
                if s > 4 {
                    boxo(ox + inset, oy + inset, s, col);
                }
                j = j + 1;
            }
            c = c + 1;
        }
        r = r + 1;
    }
    host::display::present();
}
